BEGIN EXECUTE IMMEDIATE 'DROP TABLE RELATORIO_PRIORIDADE CASCADE CONSTRAINTS'; EXCEPTION WHEN OTHERS THEN NULL; END;
/
BEGIN EXECUTE IMMEDIATE 'DROP TABLE INTERVENCAO_OPERACIONAL CASCADE CONSTRAINTS'; EXCEPTION WHEN OTHERS THEN NULL; END;
/
BEGIN EXECUTE IMMEDIATE 'DROP TABLE TRECHO_RODOVIA CASCADE CONSTRAINTS'; EXCEPTION WHEN OTHERS THEN NULL; END;
/
BEGIN EXECUTE IMMEDIATE 'DROP TABLE EQUIPE_MANUTENCAO CASCADE CONSTRAINTS'; EXCEPTION WHEN OTHERS THEN NULL; END;
/
CREATE TABLE EQUIPE_MANUTENCAO (ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, NOME VARCHAR2(100) NOT NULL, ESPECIALIDADE VARCHAR2(100) NOT NULL, DIRECAO VARCHAR2(10) DEFAULT 'NORTE' NOT NULL);"
CREATE TABLE TRECHO_RODOVIA (KM NUMBER(10) PRIMARY KEY, ALTURA_VEGETACAO NUMBER(8,2) NOT NULL, TIPO_TERRENO VARCHAR2(30) NOT NULL, EQUIPE_ID NUMBER, CONSTRAINT FK_TRECHO_EQUIPE FOREIGN KEY (EQUIPE_ID) REFERENCES EQUIPE_MANUTENCAO(ID));
CREATE TABLE INTERVENCAO_OPERACIONAL (ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, KM_TRECHO NUMBER(10) NOT NULL, TIPO VARCHAR2(60) NOT NULL, RESPONSAVEL VARCHAR2(100) NOT NULL, DATA_INTERVENCAO DATE DEFAULT SYSDATE NOT NULL, CONSTRAINT FK_INTERV_TRECHO FOREIGN KEY (KM_TRECHO) REFERENCES TRECHO_RODOVIA(KM));
CREATE TABLE RELATORIO_PRIORIDADE (ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, URGENTES NUMBER NOT NULL, CRITICOS NUMBER NOT NULL, ATENCAO NUMBER NOT NULL, NORMAIS NUMBER NOT NULL, RESUMO CLOB, GERADO_EM TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL);
